"></i> Sốc Nhiễm Khuẩn\n            </button>\n            <button class=\"preset-pill\" onclick=\"loadPreset('cardio')\">\n              <i class=\"fa-solid fa-heart-crack\" style=\"color: #d97706;\"></i> Sốc Tim\n            </button>\n            <button class=\"preset-pill\" onclick=\"loadPreset('anaphylaxis')\">\n              <i class=\"fa-solid fa-hand-dots\" style=\"color: #0284c7;\"></i> Sốc Phản Vệ\n            </button>\n            <button class=\"preset-pill\" onclick=\"loadPreset('refractory')\">\n              <i class=\"fa-solid fa-skull-crossbones\" style=\"color: #7c3aed;\"></i> Sốc Kháng Trị\n            </button>\n            <button class=\"preset-pill\" onclick=\"loadPreset('brady')\">\n              <i class=\"fa-solid fa-wave-square\" style=\"color: #0d9488;\"></i> Sốc Nhịp Chậm\n            </button>\n          </div>\n        </div>\n\n        <div class=\"control-row\" style=\"padding-top: 8px; border-top: 1px stroke var(--color-divider);\">\n          <div class=\"patient-inputs\">\n            <div class=\"patient-input-item\">\n              <label for=\"p-weight\">Cân nặng (kg):</label>\n              <input type=\"number\" id=\"p-weight\" value=\"65\" min=\"20\" max=\"250\" step=\"1\" oninput=\"updateStudio()\">\n            </div>\n            <div class=\"patient-input-item\">\n              <label for=\"p-height\">Chiều cao (cm):</label>\n              <input type=\"number\" id=\"p-height\" value=\"165\" min=\"100\" max=\"220\" step=\"1\" oninput=\"updateStudio()\">\n            </div>\n            <div class=\"patient-input-item\">\n              <label for=\"p-gender\">Giới tính:</label>\n              <select id=\"p-gender\" onchange=\"updateStudio()\">\n                <option value=\"male\">Nam</option>\n                <option value=\"female\">Nữ</option>\n              </select>\n            </div>\n          </div>\n          <div id=\"ibw-chip\" style=\"font-size: 11.5px; font-weight: 700; color: var(--vm-blue); background: var(--vm-blue-h); border: 1px solid var(--vm-blue-b); padding: 4px 10px; border-radius: 100px;\">\n            IBW: 61.3 kg | Cân nặng tính toán: 61.3 kg\n          </div>\n        </div>\n      </div>\n\n      <!-- MAIN STUDIO WORKBENCH GRID -->\n      <div class=\"studio-main-grid\">\n\n        <!-- LEFT PANEL: MULTI-PUMP ARRAY & VIS SCORE -->\n        <div class=\"card-panel\">\n          <div class=\"card-panel-head\">\n            <h3 class=\"panel-title\"><i class=\"fa-solid fa-syringes\" style=\"color: var(--vm-red);\"></i> Bảng Quản Lý Đa Bơm Tiêm Điện</h3>\n            <span style=\"font-size: 11px; font-weight: 600; color: var(--color-text-muted);\">4 Bơm Tiêm Điện Song Song</span>\n          </div>\n\n          <div class=\"pump-list\">\n            <!-- PUMP 1: NOREPINEPHRINE -->\n            <div class=\"pump-card active\" id=\"pump-card-ne\">\n              <div class=\"pump-header-row\">\n                <div class=\"pump-title-wrap\">\n                  <span class=\"pump-dot\"></span> Norepinephrine (NE)\n                </div>\n                <label class=\"pump-switch\">\n                  <input type=\"checkbox\" id=\"chk-ne\" checked onchange=\"updateStudio()\"> Bật Bơm\n                </label>\n              </div>\n              <div class=\"pump-grid-controls\">\n                <select id=\"conc-ne\" class=\"pump-select\" onchange=\"updateStudio()\">\n                  <option value=\"80\">4mg/50mL (80 mcg/mL)</option>\n                  <option value=\"160\">8mg/50mL (160 mcg/mL)</option>\n                  <option value=\"320\">16mg/50mL (320 mcg/mL)</option>\n                </select>\n                <div class=\"pump-slider-box\">\n                  <label><span>Liều cài đặt</span><strong id=\"lbl-dose-ne\">0.10 mcg/kg/min</strong></label>\n                  <input type=\"range\" id=\"sld-ne\" min=\"0\" max=\"1.5\" step=\"0.01\" value=\"0.10\" oninput=\"syncDoseInput('ne')\">\n                </div>\n                <div class=\"pump-rate-badge\">\n                  <div class=\"pump-rate-num\" id=\"rate-ne\">4.6</div>\n                  <div class=\"pump-rate-unit\">mL/giờ</div>\n                </div>\n              </div>\n            </div>\n\n            <!-- PUMP 2: VASOPRESSIN -->\n            <div class=\"pump-card\" id=\"pump-card-vaso\">\n              <div class=\"pump-header-row\">\n                <div class=\"pump-title-wrap\">\n                  <span class=\"pump-dot\"></span> Vasopressin (Sốc Kháng Trị)\n                </div>\n                <label class=\"pump-switch\">\n                  <input type=\"checkbox\" id=\"chk-vaso\" onchange=\"updateStudio()\"> Bật Bơm\n                </label>\n              </div>\n              <div class=\"pump-grid-controls\">\n                <select id=\"conc-vaso\" class=\"pump-select\" disabled>\n                  <option value=\"0.4\">20 UI/50mL (0.4 UI/mL)</option>\n                </select>\n                <div class=\"pump-slider-box\">\n                  <label><span>Liều cố định</span><strong>0.03 UI/min</strong></label>\n                  <input type=\"range\" id=\"sld-vaso\" min=\"0.01\" max=\"0.04\" step=\"0.01\" value=\"0.03\" disabled>\n                </div>\n                <div class=\"pump-rate-badge\">\n                  <div class=\"pump-rate-num\" id=\"rate-vaso\">4.5</div>\n                  <div class=\"pump-rate-unit\">mL/giờ</div>\n                </div>\n              </div>\n            </div>\n\n            <!-- PUMP 3: EPINEPHRINE -->\n            <div class=\"pump-card\" id=\"pump-card-epi\">\n              <div class=\"pump-header-row\">\n                <div class=\"pump-title-wrap\">\n                  <span class=\"pump-dot\"></span> Epinephrine (Epi)\n                </div>\n                <label class=\"pump-switch\">\n                  <input type=\"checkbox\" id=\"chk-epi\" onchange=\"updateStudio()\"> Bật Bơm\n                </label>\n              </div>\n              <div class=\"pump-grid-controls\">\n                <select id=\"conc-epi\" class=\"pump-select\" onchange=\"updateStudio()\">\n                  <option value=\"80\">4mg/50mL (80 mcg/mL)</option>\n                  <option value=\"160\">8mg/50mL (160 mcg/mL)</option>\n                </select>\n                <div class=\"pump-slider-box\">\n                  <label><span>Liều cài đặt</span><strong id=\"lbl-dose-epi\">0.05 mcg/kg/min</strong></label>\n                  <input type=\"range\" id=\"sld-epi\" min=\"0\" max=\"1.0\" step=\"0.01\" value=\"0.05\" oninput=\"syncDoseInput('epi')\">\n                </div>\n                <div class=\"pump-rate-badge\">\n                  <div class=\"pump-rate-num\" id=\"rate-epi\">2.3</div>\n                  <div class=\"pump-rate-unit\">mL/giờ</div>\n                </div>\n              </div>\n            </div>\n\n            <!-- PUMP 4: DOBUTAMINE / INOTROPE -->\n            <div class=\"pump-card\" id=\"pump-card-ino\">\n              <div class=\"pump-header-row\">\n                <div class=\"pump-title-wrap\">\n                  <span class=\"pump-dot\"></span>\n                  <select id=\"sel-ino-drug\" class=\"pump-select\" onchange=\"updateStudio()\" style=\"font-weight: 700;\">\n                    <option value=\"DOBU\">Dobutamine (Trợ tim)</option>\n                    <option value=\"DOPA\">Dopamine</option>\n                    <option value=\"PHE\">Phenylephrine</option>\n                  </select>\n                </div>\n                <label class=\"pump-switch\">\n                  <input type=\"checkbox\" id=\"chk-ino\" onchange=\"updateStudio()\"> Bật Bơm\n                </label>\n              </div>\n              <div class=\"pump-grid-controls\">\n                <select id=\"conc-ino\" class=\"pump-select\" onchange=\"updateStudio()\">\n                  <option value=\"5000\">Dobu 250mg/50mL (5000 mcg/mL)</option>\n                  <option value=\"4000\">Dopa 200mg/50mL (4000 mcg/mL)</option>\n                </select>\n                <div class=\"pump-slider-box\">\n                  <label><span>Liều cài đặt</span><strong id=\"lbl-dose-ino\">5.0 mcg/kg/min</strong></label>\n                  <input type=\"range\" id=\"sld-ino\" min=\"0\" max=\"20\" step=\"0.5\" value=\"5.0\" oninput=\"syncDoseInput('ino')\">\n                </div>\n                <div class=\"pump-rate-badge\">\n                  <div class=\"pump-rate-num\" id=\"rate-ino\">3.7</div>\n                  <div class=\"pump-rate-unit\">mL/giờ</div>\n                </div>\n              </div>\n            </div>\n          </div>\n\n          <!-- VIS SCORE SUMMARY KPI -->\n          <div class=\"vis-kpi-banner\">\n            <div>\n              <div style=\"font-size: 11px; font-weight: 700; text-transform: uppercase; color: var(--color-text-muted);\">Tổng Tải Vận Mạch &amp; Trợ Tim (VIS Score)</div>\n              <div style=\"font-size: 12px; font-weight: 600; margin-top: 2px; color: var(--color-text);\" id=\"vis-desc\">Tải nhẹ - Tiên lượng tốt</div>\n            </div>\n            <div style=\"text-align: right;\">\n              <div class=\"vis-kpi-val\" id=\"vis-score\">10.0</div>\n              <span class=\"vis-status-badge\" id=\"vis-badge\" style=\"background: var(--vm-ok-h); color: var(--vm-ok); border: 1px solid var(--vm-ok-b);\">Nguy cơ thấp</span>\n            </div>\n          </div>\n        </div>\n\n        <!-- RIGHT PANEL: HEMODYNAMIC RADAR & SHOCK MATRIX -->\n        <div class=\"card-panel\">\n          <div class=\"card-panel-head\">\n            <h3 class=\"panel-title\"><i class=\"fa-solid fa-chart-line\" style=\"color: var(--vm-blue);\"></i> Radar Sinh Hiệu &amp; Định Vị Thể Sốc</h3>\n            <span style=\"font-size: 11px; font-weight: 600; color: var(--color-text-muted);\">Vector Shock Matrix</span>\n          </div>\n\n          <div class=\"hemo-inputs-grid\">\n            <div class=\"hemo-field\">\n              <label for=\"h-sbp\">Tâm Thu SBP (mmHg)</label>\n              <input type=\"number\" id=\"h-sbp\" value=\"85\" min=\"40\" max=\"240\" step=\"1\" oninput=\"updateStudio()\">\n            </div>\n            <div class=\"hemo-field\">\n              <label for=\"h-dbp\">Tâm Trương DBP (mmHg)</label>\n              <input type=\"number\" id=\"h-dbp\" value=\"50\" min=\"20\" max=\"140\" step=\"1\" oninput=\"updateStudio()\">\n            </div>\n            <div class=\"hemo-field\">\n              <label for=\"h-hr\">Nhịp Tim HR (bpm)</label>\n              <input type=\"number\" id=\"h-hr\" value=\"115\" min=\"30\" max=\"220\" step=\"1\" oninput=\"updateStudio()\">\n            </div>\n            <div class=\"hemo-field\">\n              <label for=\"h-lactate\">Lactate (mmol/L)</label>\n              <input type=\"number\" id=\"h-lactate\" value=\"3.5\" min=\"0.5\" max=\"20\" step=\"0.1\" oninput=\"updateStudio()\">\n            </div>\n            <div class=\"hemo-field\">\n              <label for=\"h-scvo2\">ScvO2 (%)</label>\n              <input type=\"number\" id=\"h-scvo2\" value=\"62\" min=\"30\" max=\"95\" step=\"1\" oninput=\"updateStudio()\">\n            </div>\n            <div class=\"hemo-field\">\n              <label for=\"h-cvp\">Siêu âm IVC</label>\n              <select id=\"h-cvp\" onchange=\"updateStudio()\">\n                <option value=\"low\">IVC xẹp &gt; 50% (Thiếu dịch)</option>\n                <option value=\"normal\">IVC bình thường</option>\n                <option value=\"high\">IVC căng cứng (Quá tải)</option>\n              </select>\n            </div>\n          </div>\n\n          <!-- METRICS ROW -->\n          <div class=\"hemo-metrics-row\">\n            <div class=\"metric-card blue\">\n              <div class=\"metric-card-lbl\">MAP (Huyết áp Trung bình)</div>\n              <div class=\"metric-card-val\" id=\"val-map\">61.7</div>\n              <div style=\"font-size: 10px; font-weight: 700;\" id=\"lbl-map-status\">Mục tiêu ≥ 65 mmHg</div>\n            </div>\n            <div class=\"metric-card amber\">\n              <div class=\"metric-card-lbl\">SHOCK INDEX (HR / SBP)</div>\n              <div class=\"metric-card-val\" id=\"val-si\">1.35</div>\n              <div style=\"font-size: 10px; font-weight: 700;\" id=\"lbl-si-status\">Tăng cao (> 1.0)</div>\n            </div>\n          </div>\n\n          <!-- VECTOR CANVAS -->\n          <div class=\"radar-canvas-wrap\">\n            <svg class=\"radar-svg\" viewBox=\"0 0 380 220\" id=\"shock-matrix-svg\">\n              <line x1=\"190\" y1=\"15\" x2=\"190\" y2=\"205\" class=\"radar-grid-line\" />\n              <line x1=\"15\" y1=\"110\" x2=\"365\" y2=\"110\" class=\"radar-grid-line\" />\n              \n              <text x=\"25\" y=\"35\" class=\"radar-quad-text\">SỐC GIÃN MẠCH (Septic)</text>\n              <text x=\"205\" y=\"35\" class=\"radar-quad-text\">SỐC TIM (Cardiogenic)</text>\n              <text x=\"25\" y=\"195\" class=\"radar-quad-text\">SỐC GIẢM THỂ TÍCH (Hypovolemic)</text>\n              <text x=\"205\" y=\"195\" class=\"radar-quad-text\">SỐC PHỐI HỢP / KHÁNG TRỊ</text>\n\n              <circle id=\"radar-dot\" cx=\"110\" cy=\"75\" r=\"9\" fill=\"#f87171\" opacity=\"0.85\">\n                <animate attributeName=\"r\" values=\"7;11;7\" dur=\"1.5s\" repeatCount=\"indefinite\" />\n              </circle>\n              <circle id=\"radar-dot-inner\" cx=\"110\" cy=\"75\" r=\"3.5\" fill=\"#ffffff\" />\n            </svg>\n          </div>\n        </div>\n\n      </div>\n\n      <!-- ADVANCED INTERVENTIONAL MANAGEMENT PANEL (5 TABS) -->\n      <div class=\"card-panel\" style=\"margin-bottom: 18px;\">\n        <div class=\"card-panel-head\">\n          <h3 class=\"panel-title\"><i class=\"fa-solid fa-user-gear\" style=\"color: var(--vm-red);\"></i> Trung Tâm Xử Trí Can Thiệp &amp; Thủ Thuật Hồi Sức Lâm Sàng</h3>\n          <span style=\"font-size: 11px; font-weight: 600; color: var(--color-text-muted);\">EBM Action Protocols</span>\n        </div>\n\n        <div class=\"interv-tab-bar\">\n          <button class=\"interv-btn active\" onclick=\"switchTab(0)\"><i class=\"fa-solid fa-syringe\"></i> 1. Đường Truyền &amp; A-Line</button>\n          <button class=\"interv-btn\" onclick=\"switchTab(1)\"><i class=\"fa-solid fa-lungs\"></i> 2. RSI &amp; Thông Khí An Toàn</button>\n          <button class=\"interv-btn\" onclick=\"switchTab(2)\"><i class=\"fa-solid fa-water\"></i> 3. Test PLR &amp; POCUS</button>\n          <button class=\"interv-btn\" onclick=\"switchTab(3)\"><i class=\"fa-solid fa-heart-circle-bolt\"></i> 4. Trigger VA-ECMO / IABP</button>\n          <button class=\"interv-btn\" onclick=\"switchTab(4)\"><i class=\"fa-solid fa-vial-circle-check\"></i> 5. Liệu Pháp Giải Độc</button>\n        </div>\n\n        <!-- TAB 1: LINE SAFETY & EXTRAVASATION -->\n        <div class=\"interv-panel active\" id=\"tab-0\">\n          <div class=\"studio-alert\" style=\"border-left-color: var(--vm-red);\">\n            <div class=\"studio-alert-title\" style=\"color: var(--vm-red);\"><i class=\"fa-solid fa-triangle-exclamation\"></i> Chỉ định Đặt CVC &amp; Huyết Áp Động Mạch Xâm Lấn (A-Line)</div>\n            <ul style=\"margin: 4px 0 0 16px; line-height: 1.6;\">\n              <li><strong>Bắt buộc đặt Catheter Tĩnh Mạch Trung Tâm (CVC):</strong> Khi dùng Norepinephrine &ge; 0.1 mcg/kg/min hoặc phối hợp &ge; 2 thuốc vận mạch. Phòng ngừa nguy cơ hoại tử da.</li>\n              <li><strong>Chỉ định Động Mạch Xâm Lấn (A-Line):</strong> Bắt buộc khi dùng vận mạch liều cao để đo liên tục từng nhịp tim và lấy máu ABG/ScvO2 chính xác.</li>\n            </ul>\n          </div>\n\n          <div class=\"studio-alert\" style=\"border-left-color: var(--vm-amber);\">\n            <div class=\"studio-alert-title\" style=\"color: var(--vm-amber);\"><i class=\"fa-solid fa-kit-medical\"></i> Quy Trình Cấp Cứu Khi Thoát Mạch Thuốc Vận Mạch (Extravasation Rescue)</div>\n            <ol style=\"margin: 4px 0 0 16px; line-height: 1.6;\">\n              <li><strong>Dừng ngay bơm tiêm điện:</strong> Giữ nguyên kim tiêm để hút ngược 3–5 mL máu kèm thuốc thoát.</li>\n              <li><strong>Tiêm giải độc Phentolamine:</strong> Tiêm quanh vùng thoát mạch 5–10 mg Phentolamine pha trong 10 mL NaCl 0.9% bằng kim 25G.</li>\n              <li><strong>Thay thế (Nitroglycerin paste):</strong> Bôi mỏng 1–2 cm Nitroglycerin 2% ointment tại vùng thiếu máu da nếu không có Phentolamine.</li>\n            </ol>\n          </div>\n        </div>\n\n        <!-- TAB 2: RSI HEMODYNAMIC SAFETY -->\n        <div class=\"interv-panel\" id=\"tab-1\">\n          <div class=\"studio-alert\" style=\"border-left-color: var(--vm-blue);\">\n            <div class=\"studio-alert-title\" style=\"color: var(--vm-blue);\"><i class=\"fa-solid fa-mask-ventilator\"></i> Chiến Lược \"Pre-Load &amp; Push Vasoactive\" Dự Phòng Tụt HA Khi Đặt NKQ</div>\n            <p style=\"margin: 4px 0 6px;\">Dự phòng thảm họa tụt HA hoặc ngừng tim ngay sau bơm thuốc khởi mê RSI do mất trương lực giao cảm và tăng áp lực đường thở.</p>\n            <ul style=\"margin: 0 0 0 16px; line-height: 1.6;\">\n              <li><strong>Xả dịch nền &amp; Đẩy liều bolus NE:</strong> Chuẩn bị sẵn xói Bolus Norepinephrine 10–20 mcg (1–2 mL dung dịch pha loãng 10mcg/mL) trước tiêm thuốc mê.</li>\n              <li><strong>Thuốc khởi mê an toàn:</strong> Ưu tiên <strong>Etomidate 0.3 mg/kg</strong> hoặc <strong>Ketamine 1.5 mg/kg</strong>. Tránh tuyệt đối Propofol ở bệnh nhân đang tụt MAP.</li>\n            </ul>\n          </div>\n        </div>\n\n        <!-- TAB 3: PLR TEST & POCUS -->\n        <div class=\"interv-panel\" id=\"tab-2\">\n          <div class=\"studio-alert\" style=\"border-left-color: var(--vm-teal);\">\n            <div class=\"studio-alert-title\" style=\"color: var(--vm-teal);\"><i class=\"fa-solid fa-person-boating\"></i> Giả Lập Test Nâng Chân Thụ Động (PLR Test Simulator)</div>\n            <p style=\"margin: 4px 0 8px;\">Đánh giá đáp ứng bù dịch tĩnh mà không gây nguy cơ quá tải thể tích vĩnh viễn.</p>\n            <div style=\"display: flex; gap: 10px; align-items: flex-end; flex-wrap: wrap;\">\n              <div>\n                <label style=\"font-size: 11px; font-weight: 600;\">PP ban đầu (mmHg)</label>\n                <input type=\"number\" id=\"plr-pp1\" value=\"30\" style=\"width: 110px; padding: 5px; border: 1.5px solid var(--color-border); border-radius: 6px;\">\n              </div>\n              <div>\n                <label style=\"font-size: 11px; font-weight: 600;\">PP sau Nâng chân (mmHg)</label>\n                <input type=\"number\" id=\"plr-pp2\" value=\"36\" style=\"width: 110px; padding: 5px; border: 1.5px solid var(--color-border); border-radius: 6px;\">\n              </div>\n              <button class=\"btn-calc\" onclick=\"calcPLR()\">Tính % Phản Ứng</button>\n            </div>\n            <div id=\"plr-result-box\" style=\"font-weight: 700; color: var(--vm-teal); margin-top: 8px;\"></div>\n          </div>\n        </div>\n\n        <!-- TAB 4: VA-ECMO / IABP TRIGGER -->\n        <div class=\"interv-panel\" id=\"tab-3\">\n          <div class=\"studio-alert\" style=\"border-left-color: var(--vm-purple);\">\n            <div class=\"studio-alert-title\" style=\"color: var(--vm-purple);\"><i class=\"fa-solid fa-heart-pulse\"></i> Tiêu Chí Hội Chẩn Kích Hoạt VA-ECMO &amp; Bóng Đối Xung IABP</div>\n            <ul style=\"margin: 4px 0 0 16px; line-height: 1.6;\">\n              <li><strong>Chỉ số VIS &ge; 30 kéo dài:</strong> Bệnh nhân cần liều vận mạch cực cao mà MAP vẫn &lt; 65 mmHg.</li>\n              <li><strong>Tưới máu mô thất bại:</strong> $ScvO_2 &lt; 50\\%$ hoặc Lactate máu tăng liên tục $&gt; 4\\,mmol/L$ dù đã dùng Norepinephrine + Dobutamine tối đa.</li>\n              <li><strong>Hội chẩn khẩn cấp team ECMO/Tim mạch:</strong> Đánh giá đặt VA-ECMO hỗ trợ tuần hoàn cơ học cứu sống bệnh nhân.</li>\n            </ul>\n          </div>\n        </div>\n\n        <!-- TAB 5: TOXICOLOGICAL RESCUE -->\n        <div class=\"interv-panel\" id=\"tab-4\">\n          <div class=\"studio-alert\" style=\"border-left-color: var(--vm-red);\">\n            <div class=\"studio-alert-title\" style=\"color: var(--vm-red);\"><i class=\"fa-solid fa-flask-vial\"></i> Liệu Pháp Lipid Tĩnh Mạch (ILE 20%) &amp; HIET Protocol</div>\n            <ul style=\"margin: 4px 0 0 16px; line-height: 1.6;\">\n              <li><strong>Ngộ độc Thuốc tê / Chẹn Beta / Chẹn Canxi:</strong> Tiêm Bolus <strong>Lipid 20% 1.5 mL/kg</strong> trong 1–2 phút, sau đó duy trì truyền 0.25 mL/kg/phút.</li>\n              <li><strong>Liệu pháp High-Dose Insulin (HIET):</strong> Insulin Regular 1 UI/kg bolus IV + Dextrose 20–50%, duy trì 0.5–1 UI/kg/h để hỗ trợ chuyển hóa cơ tim trong sốc chẹn canxi.</li>\n            </ul>\n          </div>\n        </div>\n      </div>\n\n      <!-- UTILITY ROW (REVERSE PUMP CALCULATOR & HIS ORDER GENERATOR) -->\n      <div class=\"studio-main-grid\" style=\"margin-bottom: 0;\">\n        \n        <!-- REVERSE CALCULATOR -->\n        <div class=\"card-panel\">\n          <div class=\"card-panel-head\">\n            <h3 class=\"panel-title\"><i class=\"fa-solid fa-calculator\" style=\"color: var(--vm-teal);\"></i> Tính Ngược Tốc Độ BTĐ (mL/h &rarr; mcg/kg/min)</h3>\n          </div>\n          <div style=\"display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-bottom: 10px;\">\n            <div class=\"hemo-field\">\n              <label for=\"rev-rate\">Tốc độ BTĐ (mL/h)</label>\n              <input type=\"number\" id=\"rev-rate\" value=\"7.5\" min=\"0.1\" step=\"0.1\" oninput=\"calcReverse()\">\n            </div>\n            <div class=\"hemo-field\">\n              <label for=\"rev-drug\">Thuốc &amp; Nồng độ</label>\n              <select id=\"rev-drug\" onchange=\"calcReverse()\">\n                <option value=\"80\">NE 4mg/50mL (80 mcg/mL)</option>\n                <option value=\"160\">NE 8mg/50mL (160 mcg/mL)</option>\n                <option value=\"320\">NE 16mg/50mL (320 mcg/mL)</option>\n                <option value=\"5000\">Dobu 250mg/50mL (5000 mcg/mL)</option>\n                <option value=\"4000\">Dopa 200mg/50mL (4000 mcg/mL)</option>\n              </select>\n            </div>\n            <div class=\"hemo-field\">\n              <label for=\"rev-weight\">Cân nặng (kg)</label>\n              <input type=\"number\" id=\"rev-weight\" value=\"65\" min=\"20\" step=\"1\" oninput=\"calcReverse()\">\n            </div>\n          </div>\n          <div style=\"background: var(--vm-teal-h); border: 1px solid var(--vm-teal-b); border-radius: 9px; padding: 10px 14px; display: flex; align-items: center; justify-content: space-between;\">\n            <div style=\"font-size: 12px; font-weight: 700; color: var(--vm-teal);\">Liều bệnh nhân đang nhận:</div>\n            <div style=\"font-size: 1.4rem; font-weight: 800; color: var(--vm-teal);\" id=\"rev-result-val\">0.15 mcg/kg/phút</div>\n          </div>\n        </div>\n\n        <!-- EMR / HIS ORDER COPY BOX -->\n        <div class=\"card-panel\">\n          <div class=\"card-panel-head\">\n            <h3 class=\"panel-title\"><i class=\"fa-solid fa-file-signature\" style=\"color: var(--vm-purple);\"></i> Xuất Y Lệnh Bệnh Án &amp; HIS 1-Click</h3>\n            <button class=\"btn-copy\" onclick=\"copyHISOrder()\"><i class=\"fa-solid fa-copy\"></i> Copy Y Lệnh</button>\n          </div>\n          <div class=\"his-order-box\" id=\"his-order-text\">\n-- Đang sinh y lệnh --\n          </div>\n        </div>\n\n      </div>\n\n    </main>\n  </div>\n\n  <!-- Footer Placeholder -->\n  \n\n  <!-- JS Core & Modules -->";

